import{b}from"./api.BqjmK3op.js";const o=document.getElementById("ats-form"),n=document.getElementById("btn-scan-ats"),s=document.getElementById("ats-results"),r=document.getElementById("score-number"),a=document.getElementById("score-rationale"),i=document.getElementById("matching-skills-container"),l=document.getElementById("missing-skills-container"),d=document.getElementById("bullet-suggestions-container");o&&n&&o.addEventListener("submit",async c=>{c.preventDefault();const m=document.getElementById("resume-text")?.value,u=document.getElementById("job-desc")?.value,g=document.getElementById("job-title-input")?.value;n.setAttribute("disabled","true"),n.innerHTML="<span>Scanning with Career Hound AI...</span>";try{const e=await b(m,u,g);r&&(r.textContent=`${e.score}%`),a&&(a.textContent=e.rationale),i&&(i.innerHTML=(e.matchingSkills||[]).map(t=>`<span class="px-2.5 py-1 bg-emerald-50 text-emerald-700 rounded-lg text-xs font-semibold border border-emerald-200">✓ ${t}</span>`).join("")),l&&(l.innerHTML=(e.missingSkills||[]).map(t=>`<span class="px-2.5 py-1 bg-red-50 text-red-700 rounded-lg text-xs font-semibold border border-red-200">+ ${t}</span>`).join("")),d&&(d.innerHTML=(e.bulletSuggestions||[]).map(t=>`<li class="p-3 bg-slate-50 rounded-xl border border-slate-200/80 flex items-start gap-2"><span class="w-1.5 h-1.5 rounded-full bg-blue-600 mt-1.5 shrink-0"></span><span>${t}</span></li>`).join("")),s&&s.classList.remove("hidden"),s?.scrollIntoView({behavior:"smooth"})}catch(e){alert(e.message||"Failed to scan resume.")}finally{n.removeAttribute("disabled"),n.innerHTML='<span>Calculate Free ATS Match Score</span> <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14"></path><path d="m12 5 7 7-7 7"></path></svg>'}});
